{
  "name": "AutoGemini OBD-II",
  "description": "A high-performance automotive diagnostic and maintenance companion with AI-powered fault analysis, real-time sensor monitoring, and interactive vehicle anatomy guides.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppView {
  DASHBOARD = 'DASHBOARD',
  DTC_DETAIL = 'DTC_DETAIL',
  FAULTS = 'FAULTS',
  COMPONENTS = 'COMPONENTS',
  LIVE_MONITOR = 'LIVE_MONITOR',
  LOGS = 'LOGS',
  EMISSIONS = 'EMISSIONS',
  MAINTENANCE = 'MAINTENANCE',
  CHAT = 'CHAT',
  VISION = 'VISION'
}

export interface SensorData {
  id: string;
  name: string;
  description: string;
  value: number;
  unit: string;
  isActive: boolean;
  icon: string;
}

export interface MaintenanceItem {
  id: string;
  title: string;
  subtitle: string;
  date: string;
  mileage: string;
  cost: string;
  type: 'oil' | 'brakes' | 'general' | 'battery' | 'tires';
}

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getDTCExplanation = async (code: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Explain the OBD-II diagnostic trouble code ${code} in detail for a car owner. Include symptoms, potential causes, and suggested solutions in a professional but easy-to-understand tone. Return as JSON.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          code: { type: Type.STRING },
          description: { type: Type.STRING },
          symptoms: { type: Type.ARRAY, items: { type: Type.STRING } },
          causes: { type: Type.ARRAY, items: { type: Type.STRING } },
          solutions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["code", "description", "symptoms", "causes", "solutions"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const analyzeEngineImage = async (base64Image: string) => {
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image,
    },
  };
  const textPart = {
    text: "Identify the car parts in this image. Is there any visible damage or issues like leaks, fraying, or corrosion? Suggest maintenance steps."
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: { parts: [imagePart, textPart] },
  });

  return response.text;
};

export const startDiagnosticChat = async () => {
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: 'You are an expert automotive master technician. Help the user diagnose car issues based on symptoms they provide. Be concise, safety-conscious, and accurate.',
    },
  });
};

import React, { useState } from 'react';
import { AppView } from './types';
import Dashboard from './views/Dashboard';
import DTCDetail from './views/DTCDetail';
import Faults from './views/Faults';
import Components from './views/Components';
import LiveMonitor from './views/LiveMonitor';
import Logs from './views/Logs';
import Emissions from './views/Emissions';
import Maintenance from './views/Maintenance';
import AIChat from './views/AIChat';
import Vision from './views/Vision';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [history, setHistory] = useState<AppView[]>([]);
  const [selectedDTC, setSelectedDTC] = useState<string | null>(null);

  const navigateTo = (view: AppView, params?: any) => {
    setHistory(prev => [...prev, currentView]);
    if (view === AppView.DTC_DETAIL && params?.code) {
      setSelectedDTC(params.code);
    }
    setCurrentView(view);
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setCurrentView(prev);
    }
  };

  const renderView = () => {
    switch (currentView) {
      case AppView.DASHBOARD: return <Dashboard navigateTo={navigateTo} />;
      case AppView.FAULTS: return <Faults navigateTo={navigateTo} />;
      case AppView.DTC_DETAIL: return <DTCDetail code={selectedDTC || 'P0000'} goBack={goBack} />;
      case AppView.LIVE_MONITOR: return <LiveMonitor />;
      case AppView.CHAT: return <AIChat />;
      case AppView.VISION: return <Vision />;
      case AppView.MAINTENANCE: return <Maintenance />;
      case AppView.LOGS: return <Logs />;
      case AppView.EMISSIONS: return <Emissions />;
      case AppView.COMPONENTS: return <Components />;
      default: return <Dashboard navigateTo={navigateTo} />;
    }
  };

  const navItems = [
    { view: AppView.DASHBOARD, icon: 'grid_view', label: 'Home' },
    { view: AppView.LIVE_MONITOR, icon: 'speed', label: 'Live' },
    { view: AppView.FAULTS, icon: 'error', label: 'Faults' },
    { view: AppView.CHAT, icon: 'smart_toy', label: 'AI Help' },
    { view: AppView.VISION, icon: 'photo_camera', label: 'Vision' },
  ];

  return (
    <div className="flex flex-col h-screen max-w-md mx-auto bg-background-light dark:bg-background-dark overflow-hidden shadow-2xl">
      {/* Header */}
      <header className="px-6 py-4 flex items-center justify-between border-b border-slate-200 dark:border-white/10 bg-white/50 dark:bg-surface-dark/50 backdrop-blur-md sticky top-0 z-20">
        <div className="flex items-center gap-3">
          {history.length > 0 && (
            <button onClick={goBack} className="p-1 hover:bg-slate-100 dark:hover:bg-white/10 rounded-full transition-colors">
              <span className="material-symbols-outlined text-primary">arrow_back</span>
            </button>
          )}
          <h1 className="text-xl font-display font-bold tracking-tight text-slate-900 dark:text-white">
            Auto<span className="text-primary">Gemini</span>
          </h1>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-primary animate-pulse shadow-[0_0_8px_#13ec6d]"></div>
          <span className="text-[10px] font-bold uppercase tracking-widest text-primary">OBD-II Connected</span>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto no-scrollbar pb-24">
        {renderView()}
      </main>

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto px-4 pb-6 pt-3 bg-white/80 dark:bg-background-dark/80 backdrop-blur-xl border-t border-slate-200 dark:border-white/5 z-30">
        <div className="flex justify-between items-center bg-slate-100 dark:bg-surface-dark p-2 rounded-2xl shadow-lg border border-white/5">
          {navItems.map((item) => (
            <button
              key={item.view}
              onClick={() => setCurrentView(item.view)}
              className={`flex flex-col items-center gap-1 px-4 py-2 rounded-xl transition-all duration-300 ${
                currentView === item.view 
                  ? 'bg-primary/10 text-primary scale-110' 
                  : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'
              }`}
            >
              <span className={`material-symbols-outlined ${currentView === item.view ? 'filled' : ''}`}>
                {item.icon}
              </span>
              <span className="text-[10px] font-bold uppercase tracking-wider">{item.label}</span>
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
};

export default App;

