import React, { useEffect, useState } from 'react';
import { getDTCExplanation } from '../services/geminiService';

interface DTCData {
  code: string;
  description: string;
  symptoms: string[];
  causes: string[];
  solutions: string[];
}

const DTCDetail: React.FC<{ code: string; goBack: () => void }> = ({ code, goBack }) => {
  const [data, setData] = useState<DTCData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      try {
        const result = await getDTCExplanation(code);
        setData(result);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetch();
  }, [code]);

  if (loading) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-10 space-y-6">
        <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center space-y-2">
          <p className="text-primary font-display font-bold text-xl">Consulting Gemini AI...</p>
          <p className="text-slate-500 text-sm animate-pulse">Analyzing fault patterns & service bulletins</p>
        </div>
      </div>
    );
  }

  if (!data) return <div className="p-10 text-center">Failed to load diagnosis.</div>;

  return (
    <div className="p-6 space-y-8 animate-in fade-in duration-500">
      <div className="space-y-2">
        <div className="flex items-center gap-2">
          <span className="px-2 py-0.5 bg-red-500/10 text-red-500 rounded text-[10px] font-bold uppercase tracking-widest border border-red-500/20">Active Error</span>
          <span className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Powertrain System</span>
        </div>
        <h2 className="text-5xl font-display font-black text-slate-900 dark:text-white leading-tight">
          {data.code}
        </h2>
        <p className="text-xl text-slate-600 dark:text-slate-400 font-medium">
          {data.description}
        </p>
      </div>

      <div className="grid gap-6">
        {/* Symptoms */}
        <div className="space-y-4">
          <h3 className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-primary">
            <span className="material-symbols-outlined text-sm">list</span> Common Symptoms
          </h3>
          <ul className="grid gap-2">
            {data.symptoms.map((s, i) => (
              <li key={i} className="flex gap-3 p-3 rounded-xl bg-slate-100 dark:bg-surface-dark border border-slate-200 dark:border-white/5 text-sm text-slate-700 dark:text-slate-300">
                <span className="text-primary">•</span> {s}
              </li>
            ))}
          </ul>
        </div>

        {/* Causes */}
        <div className="space-y-4">
          <h3 className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-orange-400">
            <span className="material-symbols-outlined text-sm">history</span> Potential Causes
          </h3>
          <ul className="grid gap-2">
            {data.causes.map((c, i) => (
              <li key={i} className="flex gap-3 p-3 rounded-xl bg-slate-100 dark:bg-surface-dark border border-slate-200 dark:border-white/5 text-sm text-slate-700 dark:text-slate-300">
                <span className="text-orange-400">•</span> {c}
              </li>
            ))}
          </ul>
        </div>

        {/* Solutions */}
        <div className="space-y-4">
          <h3 className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-blue-400">
            <span className="material-symbols-outlined text-sm">build</span> Recommended Actions
          </h3>
          <div className="space-y-3">
            {data.solutions.map((s, i) => (
              <div key={i} className="p-4 rounded-2xl bg-blue-500/5 border border-blue-500/20">
                <p className="text-sm font-bold text-blue-600 dark:text-blue-400 mb-1">Step {i + 1}</p>
                <p className="text-sm text-slate-700 dark:text-slate-300">{s}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      <button
        onClick={goBack}
        className="w-full py-4 rounded-2xl bg-primary text-background-dark font-bold tracking-widest uppercase hover:opacity-90 transition-all shadow-xl shadow-primary/20"
      >
        Acknowledge & Save
      </button>
    </div>
  );
};

export default DTCDetail;

import React, { useState, useEffect } from 'react';

const LiveMonitor: React.FC = () => {
  const [sensors, setSensors] = useState({
    rpm: 850,
    speed: 0,
    coolant: 195,
    load: 12,
    throttle: 4,
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setSensors(prev => ({
        rpm: Math.floor(840 + Math.random() * 20),
        speed: prev.speed,
        coolant: prev.coolant + (Math.random() > 0.9 ? 1 : 0),
        load: Math.floor(10 + Math.random() * 5),
        throttle: prev.throttle,
      }));
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const Gauge = ({ value, label, unit, max, color = "primary" }: any) => (
    <div className="relative group">
      <div className="absolute inset-0 bg-primary/5 blur-xl group-hover:bg-primary/10 transition-all"></div>
      <div className="relative p-6 rounded-3xl bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 space-y-2">
        <div className="flex justify-between items-center">
          <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">{label}</span>
          <span className="text-xs text-slate-400">{unit}</span>
        </div>
        <div className="flex items-baseline gap-1">
          <span className={`text-4xl font-display font-bold text-slate-900 dark:text-white`}>{value}</span>
        </div>
        <div className="w-full bg-slate-100 dark:bg-white/5 h-1.5 rounded-full overflow-hidden mt-2">
          <div 
            className={`bg-${color} h-full transition-all duration-500 ease-out shadow-[0_0_8px_currentColor]`}
            style={{ width: `${(value / max) * 100}%` }}
          ></div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="p-6 space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Real-time Data</h2>
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 rounded-full bg-primary animate-ping"></span>
          <span className="text-[10px] font-bold text-primary uppercase">Streaming</span>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        <Gauge value={sensors.rpm} label="Engine RPM" unit="rev/min" max={8000} />
        <div className="grid grid-cols-2 gap-4">
          <Gauge value={sensors.coolant} label="Coolant Temp" unit="°F" max={250} color="orange-400" />
          <Gauge value={sensors.load} label="Calculated Load" unit="%" max={100} />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <Gauge value={sensors.throttle} label="Throttle Pos" unit="%" max={100} />
