        </div>
      </div>

      <div className="p-5 rounded-2xl bg-surface-dark border border-white/5 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4">
          <span className="material-symbols-outlined text-primary/20 text-6xl">query_stats</span>
        </div>
        <div className="relative z-10 space-y-1">
          <h4 className="text-white font-bold text-sm">Data Logger Active</h4>
          <p className="text-xs text-slate-500">Capturing PID parameters every 100ms.</p>
          <button className="mt-4 text-xs font-bold text-primary border-b border-primary/30 pb-0.5">View Historical Graph</button>
        </div>
      </div>
    </div>
