export default LiveMonitor;

import React, { useState, useRef, useEffect } from 'react';
import { startDiagnosticChat } from '../services/geminiService';

const AIChat: React.FC = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
    { role: 'model', text: 'Hello! I am your AutoGemini diagnostic assistant. How can I help you today? Are you seeing any warning lights or hearing unusual noises?' }
  ]);
  const [input, setInput] = useState('');
  const [chat, setChat] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      const c = await startDiagnosticChat();
      setChat(c);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim() || !chat || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const response = await chat.sendMessage({ message: userMsg });
      setMessages(prev => [...prev, { role: 'model', text: response.text }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: 'Sorry, I encountered an error. Please try again.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark">
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl ${
              m.role === 'user' 
                ? 'bg-primary text-background-dark font-medium shadow-lg' 
                : 'bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 text-slate-900 dark:text-slate-200'
            }`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.text}</p>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 p-4 rounded-2xl flex gap-2">
              <span className="w-2 h-2 bg-primary rounded-full animate-bounce"></span>
              <span className="w-2 h-2 bg-primary rounded-full animate-bounce delay-150"></span>
              <span className="w-2 h-2 bg-primary rounded-full animate-bounce delay-300"></span>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-white/80 dark:bg-background-dark/80 backdrop-blur-md border-t border-slate-200 dark:border-white/5 mb-20">
        <div className="relative flex items-center bg-slate-100 dark:bg-surface-dark rounded-2xl border border-slate-200 dark:border-white/5 p-1 px-4 shadow-inner">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
            placeholder="Describe symptoms..."
            className="flex-1 bg-transparent border-none focus:ring-0 text-slate-900 dark:text-white py-3 text-sm placeholder:text-slate-500"
          />
          <button 
            onClick={sendMessage}
            disabled={loading}
            className={`p-2 rounded-xl transition-all ${input.trim() ? 'bg-primary text-background-dark' : 'text-slate-500'}`}
          >
            <span className="material-symbols-outlined">send</span>
          </button>
        </div>
        <div className="flex gap-2 mt-3 overflow-x-auto no-scrollbar pb-1">
          {['White smoke', 'Brake squeal', 'Hard start', 'Low mpg'].map(tag => (
            <button 
              key={tag}
              onClick={() => setInput(tag)}
              className="px-3 py-1 bg-slate-100 dark:bg-surface-dark rounded-full text-[10px] font-bold text-slate-500 hover:text-primary transition-colors whitespace-nowrap uppercase tracking-widest border border-slate-200 dark:border-white/5"
            >
              {tag}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default AIChat;

import React, { useState, useRef } from 'react';
import { analyzeEngineImage } from '../services/geminiService';

const Vision: React.FC = () => {
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
    } catch (e) {
      console.error('Camera error:', e);
    }
  };

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg');
        setCapturedImage(dataUrl);
        stopCamera();
        runAnalysis(dataUrl.split(',')[1]);
      }
    }
  };

  const runAnalysis = async (base64: string) => {
    setLoading(true);
    try {
      const result = await analyzeEngineImage(base64);
      setAnalysis(result || "Could not analyze image.");
    } catch (e) {
      setAnalysis("Error analyzing image.");
    } finally {
      setLoading(false);
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Visual Diagnostic</h2>
        {capturedImage && (
          <button 
            onClick={() => { setCapturedImage(null); setAnalysis(null); startCamera(); }}
            className="text-primary text-xs font-bold uppercase tracking-widest"
          >
            Retake
          </button>
        )}
      </div>

      <div className="relative aspect-[4/3] rounded-3xl overflow-hidden bg-surface-dark border border-white/10 shadow-2xl">
        {!stream && !capturedImage && (
          <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4 p-8 text-center">
            <span className="material-symbols-outlined text-primary text-6xl">linked_camera</span>
            <p className="text-slate-400 text-sm">Point your camera at engine components, leaks, or belts for AI analysis.</p>
            <button 
              onClick={startCamera}
              className="bg-primary text-background-dark px-6 py-3 rounded-2xl font-bold tracking-widest uppercase shadow-lg shadow-primary/20"
            >
              Launch Scanner
            </button>
          </div>
        )}

        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          className={`w-full h-full object-cover ${!stream && 'hidden'}`}
        />

        {capturedImage && (
          <img src={capturedImage} className="w-full h-full object-cover" alt="Captured" />
        )}

        <canvas ref={canvasRef} className="hidden" />

        {stream && (
          <div className="absolute bottom-8 left-0 right-0 flex justify-center">
            <button 
              onClick={capture}
              className="w-16 h-16 rounded-full border-4 border-white flex items-center justify-center bg-primary/20 backdrop-blur-md"
            >
              <div className="w-12 h-12 bg-white rounded-full"></div>
            </button>
          </div>
        )}
      </div>

      {loading && (
        <div className="p-8 space-y-4 flex flex-col items-center">
          <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
          <p className="text-primary font-bold text-sm uppercase tracking-widest animate-pulse">Analyzing Visual Data...</p>
        </div>
      )}

      {analysis && (
        <div className="bg-white dark:bg-surface-dark rounded-3xl p-6 border border-slate-200 dark:border-white/5 space-y-4 animate-in fade-in slide-in-from-bottom-2">
          <div className="flex items-center gap-2">
