import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getDTCExplanation = async (code: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Explica el código de falla OBD-II ${code} en detalle para el dueño de un auto. Incluye síntomas, causas potenciales y soluciones sugeridas en un tono profesional pero fácil de entender. Responde en ESPAÑOL y formato JSON.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          code: { type: Type.STRING },
          description: { type: Type.STRING },
          symptoms: { type: Type.ARRAY, items: { type: Type.STRING } },
          causes: { type: Type.ARRAY, items: { type: Type.STRING } },
          solutions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["code", "description", "symptoms", "causes", "solutions"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const translateTechnicalText = async (text: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Traduce el siguiente texto técnico automotriz del inglés al español: "${text}". Asegúrate de usar la terminología mecánica correcta utilizada en talleres profesionales.`,
    config: {
      systemInstruction: "Eres un traductor experto especializado en ingeniería automotriz y mecánica. Traduces manuales de taller, reportes de diagnóstico y descripciones técnicas de componentes con precisión milimétrica."
    }
  });
  return response.text;
};

export const analyzeEngineImage = async (base64Image: string) => {
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image,
    },
  };
  const textPart = {
    text: "Identifica las partes del auto en esta imagen en español. ¿Hay algún daño visible como fugas, cables pelados o corrosión? Sugiere pasos de mantenimiento."
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: { parts: [imagePart, textPart] },
  });

  return response.text;
};

