          <span className="text-[10px] font-bold uppercase tracking-widest text-primary">OBD-II Conectado</span>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto no-scrollbar pb-24">
        {renderView()}
      </main>

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto px-4 pb-6 pt-3 bg-white/80 dark:bg-background-dark/80 backdrop-blur-xl border-t border-slate-200 dark:border-white/5 z-30">
        <div className="flex justify-between items-center bg-slate-100 dark:bg-surface-dark p-2 rounded-2xl shadow-lg border border-white/5">
          {navItems.map((item) => (
            <button
